edits.after:
// Two complete owned acceptance stages. Reservation advances at capture;
// the original fill frontier advances only when a validated tuple commits.
identity_t captured_meta, captured_expected_meta, reserved_meta;
logic captured_valid, commit_valid;
logic captured_bank, captured_expected_owned, captured_token_exhausted;
logic captured_metadata_bad, captured_domain_bad;
logic [5:0] captured_index, captured_expected_index;
logic [15:0] captured_value;
logic reserve_bank;
logic [5:0] reserve_index;
logic [31:0] reserved_token;
logic [1:0] accept_state;

// Input eligibility never looks through downstream readiness or through a
// validation result. A captured tuple is checked one edge later and commits
// on the following edge; an older commit may retire on a younger fault edge.
assign frontier_bank=reserve_bank;
assign frontier_index=reserve_index;
assign frontier_token=reserved_token;
assign frontier_meta=reserved_meta;
assign accept_state=commit_valid?A_COMMIT:captured_valid?A_VALIDATE:A_EMPTY;
assign accept_pending=captured_valid||commit_valid;

edits.before:
// A committing tuple owns the next frontier. Forward only registered slot
// operands; this permits complete pop/push replacement at II=2.
assign frontier_bank=coefficient_commit&&expected_index==63 ? !accepted_bank : fill_bank;
assign frontier_index=coefficient_commit ? expected_index+6'd1 : fill_index;
assign frontier_token=coefficient_commit&&expected_index==0 ? accepted_meta.token : next_token;
always_comb begin
    frontier_meta='{epochs[frontier_bank],child_epochs[frontier_bank],tokens[frontier_bank],planes[frontier_bank],scales[frontier_bank],blocks[frontier_bank],tiles[frontier_bank],cells[frontier_bank]};
    if(coefficient_commit&&expected_index==0)frontier_meta=accepted_meta;
end
assign accept_pending=accept_state!=A_EMPTY;

edits.after:
if(captured_valid)begin
    if(captured_index!=captured_expected_index)input_fault=1;
    else if(input_metadata_bad)input_fault=2;
    else if(captured_domain_bad)input_fault=3;
    else if(captured_expected_index==0&&captured_token_exhausted)input_fault=7;
end else if(finished_input&&!accept_pending&&fill_index!=0)input_fault=4;

edits.before:
if(accept_state==A_VALIDATE)begin
    if(accepted_index!=expected_index)input_fault=1;
    else if(input_metadata_bad)input_fault=2;
    else if(accepted_domain_bad)input_fault=3;
    else if(expected_index==0&&token_exhausted)input_fault=7;
end else if(finished_input&&accept_state==A_EMPTY&&fill_index!=0)input_fault=4;

edits.after:
captured_valid<=in_valid&&in_ready;
commit_valid<=captured_valid;
if(captured_valid)begin
    accepted_meta<=captured_meta;expected_meta<=captured_expected_meta;
    accepted_bank<=captured_bank;accepted_index<=captured_index;
    expected_index<=captured_expected_index;accepted_value<=captured_value;
    accepted_metadata_bad<=captured_metadata_bad;accepted_domain_bad<=captured_domain_bad;
    expected_owned<=captured_expected_owned;token_exhausted<=captured_token_exhausted;
end
if(in_valid&&in_ready)begin
    count_inputs<=count_inputs+1;
    captured_meta<='{in_epoch,in_child_epoch,frontier_index==0?frontier_token+1:frontier_meta.token,in_plane,in_qscale,in_block,in_tile,in_qcell};
    captured_expected_meta<=frontier_meta;
    captured_bank<=frontier_bank;captured_index<=in_index;captured_expected_index<=frontier_index;captured_value<=in_value;
    captured_metadata_bad<=in_metadata_bad;captured_domain_bad<=in_domain_bad;
    captured_expected_owned<=frontier_index!=0;captured_token_exhausted<=frontier_token==32'hffffffff;
    if(frontier_index==0)begin
        reserved_meta<='{in_epoch,in_child_epoch,frontier_token+1,in_plane,in_qscale,in_block,in_tile,in_qcell};
        reserved_token<=frontier_token+1;
    end
    if(frontier_index==63)begin reserve_bank<=!frontier_bank;reserve_index<=0;end
    else reserve_index<=frontier_index+1;
end
// This counter records the real validated-word payload write even
// if a younger captured tuple faults on the same edge. That word is
// private: fail revokes both bank owners before any new publication.
if(coefficient_commit)count_commits<=count_commits+1;
if(input_fault!=0)fail(input_fault);
else begin
    if(coefficient_commit)begin
        if(expected_index==0)begin
            epochs[accepted_bank]<=accepted_meta.epoch;child_epochs[accepted_bank]<=accepted_meta.child;
            planes[accepted_bank]<=accepted_meta.plane;scales[accepted_bank]<=accepted_meta.scale;
            blocks[accepted_bank]<=accepted_meta.block;tiles[accepted_bank]<=accepted_meta.tile;cells[accepted_bank]<=accepted_meta.qcell;
            tokens[accepted_bank]<=accepted_meta.token;next_token<=accepted_meta.token;bank_state[accepted_bank]<=FILL;
        end
        if(expected_index==63)begin
            bank_state[accepted_bank]<=READY;fill_bank<=!accepted_bank;fill_index<=0;count_tiles<=count_tiles+1;
        end else fill_index<=expected_index+1;
    end

edits.before:
if(in_valid&&in_ready)begin
    count_inputs<=count_inputs+1;accept_state<=A_VALIDATE;
    accepted_meta<='{in_epoch,in_child_epoch,frontier_token+1,in_plane,in_qscale,in_block,in_tile,in_qcell};
    expected_meta<=frontier_meta;
    accepted_bank<=frontier_bank;accepted_index<=in_index;expected_index<=frontier_index;accepted_value<=in_value;
    accepted_metadata_bad<=in_metadata_bad;accepted_domain_bad<=in_domain_bad;
    expected_owned<=frontier_index!=0;token_exhausted<=frontier_token==32'hffffffff;
end
if(input_fault!=0)fail(input_fault);
else begin
    if(accept_state==A_VALIDATE)accept_state<=A_COMMIT;
    if(coefficient_commit)begin
        count_commits<=count_commits+1;accept_state<=in_valid&&in_ready?A_VALIDATE:A_EMPTY;
        if(expected_index==0)begin
            epochs[accepted_bank]<=accepted_meta.epoch;child_epochs[accepted_bank]<=accepted_meta.child;
            planes[accepted_bank]<=accepted_meta.plane;scales[accepted_bank]<=accepted_meta.scale;
            blocks[accepted_bank]<=accepted_meta.block;tiles[accepted_bank]<=accepted_meta.tile;cells[accepted_bank]<=accepted_meta.qcell;
            tokens[accepted_bank]<=accepted_meta.token;next_token<=accepted_meta.token;bank_state[accepted_bank]<=FILL;
        end
        if(expected_index==63)begin
            bank_state[accepted_bank]<=READY;fill_bank<=!accepted_bank;fill_index<=0;count_tiles<=count_tiles+1;
        end else fill_index<=expected_index+1;
    end

edits.after:
`ifndef SYNTHESIS
    always_ff @(posedge clk)if(!kill&&running)begin
        assert(accept_pending==(accept_state!=A_EMPTY))else $fatal(1,"inverse acceptance state view mismatch");
        if(coefficient_commit)begin
            assert(accepted_index==expected_index&&!accepted_metadata_bad&&!accepted_domain_bad)else $fatal(1,"inverse unvalidated commit");
            assert(!(expected_index==0&&token_exhausted))else $fatal(1,"inverse exhausted token committed");
            if(expected_owned)assert(accepted_meta.epoch==expected_meta.epoch&&accepted_meta.child==expected_meta.child&&
                accepted_meta.plane==expected_meta.plane&&accepted_meta.scale==expected_meta.scale&&accepted_meta.block==expected_meta.block&&
                accepted_meta.tile==expected_meta.tile&&accepted_meta.qcell==expected_meta.qcell)else $fatal(1,"inverse committed metadata incoherent");
        end
        assert(count_commits<=count_inputs)else $fatal(1,"inverse commit exceeds accepted frontier");
        assert(count_inputs-count_commits==64'(captured_valid)+64'(commit_valid))else $fatal(1,"inverse accepted/committed occupancy mismatch");
        if(coefficient_commit&&expected_index==0)assert(accepted_meta.token==next_token+1)else $fatal(1,"inverse committed token frontier mismatch");
        if(in_valid&&in_ready&&frontier_index==0)assert(bank_state[frontier_bank]==FREE)else $fatal(1,"inverse reservation reused owned coefficient bank");
    end
`endif
endmodule
